package com.luxora.commerce.checkout.service;
import com.luxora.commerce.cart.service.CartService; import com.luxora.commerce.catalog.model.*; import com.luxora.commerce.catalog.repository.ProductVariantRepository; import com.luxora.commerce.checkout.dto.*; import com.luxora.commerce.common.exception.*; import com.luxora.commerce.promotion.service.PromotionService; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Service;
@Service public class CheckoutCalculationService {private static final BigDecimal ZERO=BigDecimal.ZERO; private static final String CURRENCY="USD"; private final CartService cartService; private final ProductVariantRepository variantRepository; private final PromotionService promotionService; public CheckoutCalculationService(CartService c,ProductVariantRepository v,PromotionService p){cartService=c;variantRepository=v;promotionService=p;}
public CheckoutCalculation calculate(UUID userId,CheckoutPreviewRequest request,boolean lockInventory){Map<UUID,Integer> quantities=cartService.getAuthenticatedCartQuantities(userId);if(quantities.isEmpty())throw new BadRequestException("EMPTY_CART","Cart is empty");List<CheckoutCalculationItem> items=quantities.entrySet().stream().map(e->item(e.getKey(),e.getValue(),lockInventory)).sorted(Comparator.comparing(CheckoutCalculationItem::name).thenComparing(CheckoutCalculationItem::sku)).toList();BigDecimal subtotal=items.stream().map(CheckoutCalculationItem::lineTotal).reduce(ZERO,BigDecimal::add);PromotionService.AppliedPromotion promotion=promotionService.apply(request.promotionCode(),subtotal,lockInventory);return new CheckoutCalculation(items,address(request),subtotal,ZERO,ZERO,promotion.discountAmount(),subtotal.subtract(promotion.discountAmount()),CURRENCY,promotion);}
private CheckoutCalculationItem item(UUID id,int quantity,boolean lock){if(quantity<=0)throw new BadRequestException("INVALID_QUANTITY","Quantity must be greater than zero");ProductVariant v=(lock?variantRepository.findWithProductByIdForUpdate(id):variantRepository.findWithProductById(id)).orElseThrow(()->new NotFoundException("VARIANT_NOT_FOUND","Product variant not found"));Product p=v.getProduct();if(!v.isActive()||!p.isActive())throw new BadRequestException("VARIANT_UNAVAILABLE","Product variant is unavailable");if(v.getInventoryItem().getQuantityAvailable()<quantity)throw new BadRequestException("INSUFFICIENT_STOCK","Not enough stock for selected variant");String image=p.getImages().stream().min(Comparator.comparingInt(ProductImage::getDisplayOrder)).map(ProductImage::getUrl).orElse(null);return new CheckoutCalculationItem(v,p.getId(),v.getId(),p.getSlug(),p.getName(),v.getSku(),v.getColor(),v.getStorage(),image,v.getPrice(),quantity,v.getPrice().multiply(BigDecimal.valueOf(quantity)));}
private ShippingAddressResponse address(CheckoutPreviewRequest r){return new ShippingAddressResponse(r.recipientName().trim(),r.phone().trim(),r.addressLine1().trim(),trim(r.addressLine2()),r.city().trim(),r.province().trim(),r.country().trim(),trim(r.postalCode()));} private String trim(String s){return s==null||s.isBlank()?null:s.trim();}}